from lib import *
S = SS('x84')
steps = [
    step("先看构建。同一个 webmvc 应用,普通 mvn package 11 秒,得到 18.9 MB 的 app.jar;mvn -Pnative native:compile 用了 102 秒(这次的耗时里可能包含第一次下载 native 插件的时间),/usr/bin/time -l 报告的最大常驻内存约 2737 MB,得到一个 74.3 MB 的原生可执行文件 target/app,不需要 JDK。构建之前 Spring AOT 先把 Bean 定义「预先算好」:target/spring-aot/main 下有 classes、resources、sources 三个目录,生成了 52 个 Java 源文件,名字形如 AopAutoConfiguration__BeanDefinitions.java、ApplicationAvailabilityAutoConfiguration__BeanDefinitions.java——把原来运行时靠反射和条件判断做的事,变成了编译期生成的普通代码。", t=tl(S(1)), mark=lidx(S(1), '原生构建', '原生可执行文件'), done=lidx(S(1), '普通构建', '生成的 Java 源文件'), b=bars([['普通构建用时(秒)', 11, '11'], ['原生构建用时(秒)', 102, '102'], ['app.jar 大小(MB)', 19, '18.9'], ['原生可执行文件大小(MB)', 74, '74.3']], 102, done=[0, 2], mark=[1, 3]), kv=KV([['构建时间', '11 秒 → 102 秒'], ['构建内存', '原生构建峰值约 2737 MB'], ['产物', '18.9 MB jar → 74.3 MB 单文件'], ['Spring AOT', '生成 52 个 Java 源文件']], ['构建时间'])),
    step("启动、内存、第一次请求(各 5 次取中位数,同一台机器)。JVM 跑 jar:端口可连接中位 1023 ms(范围 971 到 1213),第 1 次请求 38.0 ms,常驻内存启动后 185 MB、请求 2 次后 196 MB。JVM 但用 Spring AOT 生成的代码(-Dspring.aot.enabled=true):中位 839 ms(范围 725 到 1910,有一次异常慢),第 1 次请求 43.3 ms,常驻内存 171 MB 和 173 MB——不用原生镜像,只用 AOT 就快了一些、内存也少了一些。原生镜像:端口可连接中位 28 ms(范围 28 到 1349,同样有一次异常慢),第 1 次请求 7.3 ms,常驻内存启动后 63 MB、请求 2 次后 73 MB。启动时间差了约 36 倍(1023 对 28,算出来的比值),内存只有 JVM 的三分之一左右。", t=tl(S(2)), mark=lidx(S(2), '原生镜像:./target/app'), done=lidx(S(2), 'JVM:java -jar', 'JVM + Spring AOT'), b=bars([['JVM jar 启动(ms)', 1023, '1023'], ['JVM + AOT 启动(ms)', 839, '839'], ['原生镜像启动(ms)', 28, '28'], ['JVM jar 请求后常驻内存(MB)', 196, '196'], ['原生镜像请求后常驻内存(MB)', 73, '73']], 1023, done=[1], mark=[2, 4], cur=[0, 3]), kv=KV([['JVM jar', '1023 ms,196 MB'], ['JVM + AOT', '839 ms,173 MB'], ['原生镜像', '28 ms,73 MB'], ['第 1 次请求', '38.0 ms → 7.3 ms']], ['原生镜像'])),
    step("封闭世界:运行时才决定的东西在原生镜像里不一样。/runtime 返回:JVM 是 java.vm.name=OpenJDK 64-Bit Server VM,原生镜像是 Substrate VM,org.graalvm.nativeimage.imagecode=runtime。用 Class.forName 按名字加载一个普通类 demo.Hidden:JVM 里 loaded;原生镜像里 FAIL ClassNotFoundException: demo.Hidden——构建时没有任何地方告诉它这个类会被反射使用,就被裁掉了。给 demo.Hinted 用 @ImportRuntimeHints 注册了反射提示:原生镜像里也 loaded。再看 profile:启动时加 --spring.profiles.active=dev,JVM 里 @Profile(\"dev\") 的 devMarker 存在=true;原生镜像里 activeProfiles 虽然是 [dev],devMarker 存在=false——Bean 定义在构建期就定死了,运行时再激活 profile 创建不出构建期没有包含的 Bean。", t=tl(S(3)), mark=lidx(S(3), 'demo.Hidden', '启动时加 --spring.profiles.active=dev:GET /beans → devMarker 存在=false'), done=lidx(S(3), 'demo.Hinted', 'imagecode', 'devMarker 存在=true'), b=bars([['JVM:加载 demo.Hidden(1=成功)', 1, '成功'], ['原生:加载 demo.Hidden', 0, 'ClassNotFoundException'], ['原生:加载有提示的 demo.Hinted', 1, '成功'], ['JVM:dev 下 devMarker 存在', 1, 'true'], ['原生:dev 下 devMarker 存在', 0, 'false']], 1, done=[0, 2, 3], mark=[1, 4]), kv=KV([['反射', '没有提示的类被裁掉,ClassNotFoundException'], ['提示', '@ImportRuntimeHints 注册后可用'], ['@Profile', 'Bean 定义构建期定死,运行时激活 dev 也没有 devMarker'], ['VM', 'Substrate VM,没有 JIT']], ['@Profile'])),
    step("预热之后的吞吐(JDK HttpClient + 虚拟线程,并发 64,预热 3 秒再测 6 秒,3 轮)。JVM:62376、55517、62004 请求/秒,中位 62004,p99 2.2 到 3.4 ms,压测后常驻内存 302 MB。原生镜像:54315、55327、54197 请求/秒,中位 54315,p99 2.8 到 3.2 ms,压测后常驻内存 78 MB。稳定之后 JVM 的吞吐更高(中位 62004 对 54315,约高 14%,算出来的),但原生镜像用的内存只有 JVM 的四分之一左右。所以原生镜像换来的是启动速度和内存,不是吞吐;长期运行的服务,JIT 把热点编译优化之后吞吐上是有优势的。这个对比只测了一个最简单的接口,别的负载下结论可能不同。", t=tl(S(4)), mark=lidx(S(4), 'JVM:java -jar'), done=lidx(S(4), '原生镜像'), b=bars([['JVM 中位吞吐(请求/秒)', 62004, '62004'], ['原生镜像中位吞吐', 54315, '54315'], ['JVM 压测后常驻内存(MB)', 302, '302'], ['原生镜像压测后常驻内存(MB)', 78, '78']], 62004, done=[0, 3], mark=[1, 2]), kv=KV([['吞吐', 'JVM 62004,原生 54315 请求/秒'], ['延迟', 'p99 都在 2 到 3.4 ms'], ['内存', '302 MB 对 78 MB'], ['结论', '原生换来启动与内存,不是吞吐']], ['结论'])),
]
A = mkartx('x84', 84, 'Spring,Boot,GraalVM,Native Image,AOT,启动,真实验证,动画演示',
    '实测 Spring Boot 4.0.8 加 GraalVM 25 原生镜像:构建 102 秒、峰值内存约 2737 MB、产物 74.3 MB;启动从 1023 ms 降到 28 ms,常驻内存 196 MB 降到 73 MB;没有反射提示的类会 ClassNotFoundException,运行时激活的 @Profile 不生效;稳定之后吞吐比 JVM 低约 14%。',
    '原生镜像到底换来什么、付出什么?启动快多少、内存省多少?为什么原生镜像里按名字反射会失败?profile 在原生镜像里为什么不能运行时再改?这篇用同一个应用对比 JVM、JVM 加 AOT、原生镜像。',
    [('1023 → 28 ms', 'JVM 跑 jar 与原生镜像的端口可连接时间中位数'), ('ClassNotFoundException', '没有反射提示的类在原生镜像里按名字加载会失败'), ('62004 vs 54315', '预热之后 JVM 与原生镜像的吞吐中位数(请求/秒)')],
    [('构建的代价', '<p>构建 102 秒、峰值内存约 2737 MB;产物是 74.3 MB 的单文件;Spring AOT 先生成 52 个 Java 源文件。</p>'),
     ('启动与内存', '<p>启动 1023 ms → 28 ms;请求后常驻内存 196 MB → 73 MB;只用 Spring AOT 的 JVM 模式也略快。</p>'),
     ('封闭世界', '<p>没有提示的反射类被裁掉;Bean 定义与 profile 在构建期定死。</p>'),
     ('吞吐', '<p>稳定之后 JVM 的吞吐更高,原生镜像省的是启动时间与内存。</p>')],
    steps,
    [ENV_X + '。JVM 模式用 OpenJDK 21.0.12;原生镜像用 GraalVM Community 25.0.2(native-image),通过 spring-boot-starter-parent 的 native profile 与 native-maven-plugin 构建,-J-Xmx6g 限制 native-image 的堆;应用 spring-boot-starter-webmvc 加几个演示用接口;启动、内存各 5 次取中位数,吞吐 3 轮;最大常驻内存取自 /usr/bin/time -l;测试时机器上有别的程序在运行,所以只比较同一次运行里的数字',
     '没有验证:Spring Data、Security、模板引擎等更多依赖下的原生镜像可用性与构建时间;Linux 容器里的静态链接与 distroless 镜像;PGO(--pgo)与 G1 垃圾回收器对吞吐的补偿;构建缓存与 CI 成本;原生镜像的调试与 JFR;反射提示用 @RegisterReflectionForBinding、元数据仓库自动补充的情形;对第 74 篇里 CDS 的对比(没有放在同一个应用上);102 秒里有多少是下载插件'],
    '原生镜像')
